/**
 * Loader for the B1 finding-inbox oracle vectors.
 *
 * The fixture is generated by `apps/crq-python/finding_inbox_vector_emit_b1.py`
 * from the real `finding_delivery.Inbox`. It contains no paths, host data or
 * credentials; tests compare exact canonical bytes, effect order and Python
 * exception classes.
 */
import { readFileSync } from 'node:fs';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  toPlainJson,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import { sha256Hex } from '../../../src/policy/crq/pythonJson.js';

const VECTOR_URL = new URL(
  '../../../apps/crq-python/fixtures/crq-finding-inbox-b1/vectors.json',
  import.meta.url,
);

export interface FindingDeliveryCase {
  readonly family: string;
  readonly name: string;
  readonly source: string;
  readonly input: JsonObject;
  readonly expect: JsonObject;
}

export function requireObject(value: JsonValue | undefined, what: string): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error(`${what}: expected an object`);
  return value;
}

export function requireArray(value: JsonValue | undefined, what: string): readonly JsonValue[] {
  if (!Array.isArray(value)) throw new Error(`${what}: expected an array`);
  return value;
}

export function requireString(value: JsonValue | undefined, what: string): string {
  if (typeof value !== 'string') throw new Error(`${what}: expected a string`);
  return value;
}

export function requireNumber(value: JsonValue | undefined, what: string): number {
  if (value instanceof JsonNumber) {
    if (value.integer !== null) return Number(value.integer);
    if (value.float !== null) return value.float;
  }
  if (typeof value === 'number') return value;
  throw new Error(`${what}: expected a number`);
}

export function objectField(object: JsonObject, key: string): JsonObject {
  return requireObject(object.get(key), key);
}

export function arrayField(object: JsonObject, key: string): readonly JsonValue[] {
  return requireArray(object.get(key), key);
}

export function stringField(object: JsonObject, key: string): string {
  return requireString(object.get(key), key);
}

export function numberField(object: JsonObject, key: string): number {
  return requireNumber(object.get(key), key);
}

export function optionalObjectField(object: JsonObject, key: string): JsonObject | undefined {
  const value = object.get(key);
  return value === undefined ? undefined : requireObject(value, key);
}

export function optionalArrayField(object: JsonObject, key: string): readonly JsonValue[] {
  const value = object.get(key);
  return value === undefined ? [] : requireArray(value, key);
}

export function loadFindingDeliveryVectors(): readonly FindingDeliveryCase[] {
  const parsed = parseJsonValue(readFileSync(VECTOR_URL, 'utf8'));
  const document = requireObject(parsed, 'vectors');
  const cases: FindingDeliveryCase[] = [];
  for (const familyValue of arrayField(document, 'families')) {
    const family = requireObject(familyValue, 'family');
    const name = stringField(family, 'family');
    for (const caseValue of arrayField(family, 'cases')) {
      const entry = requireObject(caseValue, `${name} case`);
      cases.push({
        family: name,
        name: stringField(entry, 'name'),
        source: stringField(entry, 'source'),
        input: objectField(entry, 'input'),
        expect: objectField(entry, 'expect'),
      });
    }
  }
  return cases;
}

export interface RowEvidence {
  readonly id: string;
  readonly canonical: string;
  readonly sha256: string;
}

export function rowEvidence(value: JsonValue): RowEvidence {
  const row = requireObject(value, 'row');
  const canonical = stringField(row, 'canonical');
  const id = stringField(row, 'id');
  const sha256 = stringField(row, 'sha256');
  if (sha256Hex(new TextEncoder().encode(canonical)) !== sha256) {
    throw new Error(`row ${id}: sha256 does not match canonical bytes`);
  }
  return { id, canonical, sha256 };
}

export function rowsFrom(value: JsonValue | undefined): readonly RowEvidence[] {
  if (value === undefined) return [];
  return requireArray(value, 'rows').map(rowEvidence);
}

export function effectsFrom(expect: JsonObject): readonly JsonObject[] {
  const value = expect.get('effects');
  if (value === undefined) return [];
  return requireArray(value, 'effects').map((effect) => requireObject(effect, 'effect'));
}

export function plain(value: JsonValue): unknown {
  return toPlainJson(value);
}
